package tech.qiantong.qdata.module.dp.warehouse;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.transaction.support.TransactionTemplate;
import tech.qiantong.qdata.common.core.domain.entity.SysUser;
import tech.qiantong.qdata.common.core.domain.model.LoginUser;
import tech.qiantong.qdata.module.att.service.client.ClientResourceAccess;
import tech.qiantong.qdata.security.web.service.ProjectPermissionService;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;

@EnabledIfEnvironmentVariable(named="QDATA_NAMESPACE_INTEGRATION",matches="true")
class WarehouseOperationProjectIntegrationTest {
    SingleConnectionDataSource fixture;JdbcTemplate jdbc;TransactionTemplate tx;ProjectPermissionService permissions;
    WarehouseSpaceService spaces;WarehouseService models;WarehouseOperationAccess operations;WarehouseController controller;WarehouseDefinition a,b;
    @BeforeEach void setup(){
        String url=System.getenv("QDATA_WAREHOUSE_CAPABILITY_URL");assertNotNull(url);assertTrue(url.contains("/qdata_warehouse_capability_"));fixture=new SingleConnectionDataSource(url,"root",System.getenv("QDATA_NAMESPACE_PASSWORD"),true);jdbc=new JdbcTemplate(fixture);tx=new TransactionTemplate(new DataSourceTransactionManager(fixture));
        var user=new SysUser();user.setUserId(927L);user.setUserName("warehouse-capability-fixture");user.setRoles(List.of());SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new LoginUser(927L,null,user,Set.of("*:*:*")),null,List.of()));
        permissions=new ProjectPermissionService(jdbc);spaces=mock(WarehouseSpaceService.class);models=mock(WarehouseService.class);
        when(spaces.projects()).thenReturn(List.of(Map.of("id",143L,"name","read"),Map.of("id",144L,"name","write")));
        var first=new WarehouseSpaceService.Space();first.setId(900144L);first.setProjectId(144L);first.setDatasourceId(9L);first.setEngineId(1L);
        var second=new WarehouseSpaceService.Space();second.setId(900143L);second.setProjectId(143L);second.setDatasourceId(9L);second.setEngineId(1L);
        when(spaces.getInternal(900144L)).thenReturn(first);when(spaces.getInternal(900143L)).thenReturn(second);when(spaces.spaces()).thenReturn(List.of(first,second));
        a=new WarehouseDefinition();a.setId(900001L);a.setSpaceId(900144L);a.setColumns(List.of());a.setUpstreamIds(List.of());a.setDimensions(List.of());b=new WarehouseDefinition();b.setId(900002L);b.setSpaceId(900143L);b.setColumns(List.of());b.setUpstreamIds(List.of());b.setDimensions(List.of());
        when(models.getInternal(900001L)).thenReturn(a);when(models.getInternal(900002L)).thenReturn(b);when(models.list()).thenReturn(List.of(a,b));operations=new WarehouseOperationAccess(jdbc,spaces,models,permissions);controller=new WarehouseController(models,spaces,operations);
    }
    @AfterEach void finish(){SecurityContextHolder.clearContext();fixture.destroy();}
    void grant(long role,String permission){jdbc.update("INSERT INTO system_role_menu(role_id,menu_id) SELECT ?,m.menu_id FROM system_menu m WHERE m.perms=? AND NOT EXISTS(SELECT 1 FROM system_role_menu r WHERE r.role_id=? AND r.menu_id=m.menu_id)",role,permission,role);}
    @Test void differentProjectManagementPermissionsCannotBeCombined(){assertTrue(permissions.has(144L,"dp:model:edit"));assertTrue(permissions.has(144L,"att:project:edit"));assertTrue(permissions.has(143L,"da:dataSource:edit"));assertFalse(operations.canManage());var engine=new WarehouseSpaceService.Engine();engine.setDatasourceId(9L);assertThrows(AccessDeniedException.class,()->controller.engine(engine));verify(spaces,never()).registerEngine(any());}
    @Test void managementWorksWhenAllPermissionsBelongToAssignedProject(){tx.executeWithoutResult(status->{grant(19,"da:dataSource:edit");assertTrue(operations.canManage());var engine=new WarehouseSpaceService.Engine();engine.setDatasourceId(9L);assertDoesNotThrow(()->operations.engine(engine));var space=new WarehouseSpaceService.Space();space.setProjectId(144L);assertDoesNotThrow(()->operations.manageSpace(space));space.setProjectId(143L);assertThrows(AccessDeniedException.class,()->operations.manageSpace(space));status.setRollbackOnly();});}
    @Test void modelAndSpaceReadsWorkInBothProjects(){assertDoesNotThrow(()->operations.space(900143L,"dp:model:query"));assertDoesNotThrow(()->operations.space(900144L,"dp:model:query"));assertEquals(2,operations.visibleModels("dp:model:list").size());}
    @Test void readonlyProjectCannotSaveOrExecuteModels(){assertThrows(AccessDeniedException.class,()->controller.save(b));assertThrows(AccessDeniedException.class,()->controller.execute(900002L,"DDL"));verify(models,never()).save(any(),anyString(),anyLong());verify(models,never()).start(anyLong(),anyString(),anyString());assertDoesNotThrow(()->controller.save(a));verify(models).save(eq(a),anyString(),eq(927L));}
    @Test void requestedDestinationDoesNotHideExistingModelOwner(){var request=new WarehouseDefinition();request.setId(900002L);request.setSpaceId(900144L);assertThrows(AccessDeniedException.class,()->operations.definition(request,"dp:model:add","dp:model:edit"));}
    @Test void upstreamReferencesRequireTheirOwnReadPermission(){tx.executeWithoutResult(status->{jdbc.update("DELETE rm FROM system_role_menu rm JOIN system_menu m ON m.menu_id=rm.menu_id WHERE rm.role_id=20 AND m.perms='dp:model:query'");a.setUpstreamIds(List.of(900002L));assertThrows(AccessDeniedException.class,()->operations.definition(a,"dp:model:add","dp:model:edit"));status.setRollbackOnly();});}
    @Test void ownershipAloneDoesNotMakeModelsVisibleWithoutFunctionPermission(){tx.executeWithoutResult(status->{jdbc.update("DELETE rm FROM system_role_menu rm JOIN system_menu m ON m.menu_id=rm.menu_id WHERE rm.role_id=20 AND m.perms='dp:model:list'");assertEquals(List.of(a),operations.visibleModels("dp:model:list"));status.setRollbackOnly();});}
    @Test void capabilitiesReflectEachProjectInsteadOfMergedLoginMenus(){var read=operations.capabilities(900143L);var write=operations.capabilities(900144L);assertFalse(read.get("modelWrite"));assertFalse(read.get("modelExecute"));assertFalse(read.get("qualityWrite"));assertFalse(read.get("servingPublish"));assertTrue(write.get("modelWrite"));assertTrue(write.get("qualityWrite"));assertTrue(write.get("servingPublish"));}
    @Test void batchExecutionIsDeniedBeforeRegistryCallForReaderProject(){var registry=mock(WarehouseBatchRegistry.class);var endpoint=new WarehouseBatchController(registry,mock(WarehouseBatchExecutor.class),spaces,mock(WarehouseCatalogService.class),operations);assertThrows(AccessDeniedException.class,()->endpoint.start("cap-b"));verifyNoInteractions(registry);assertDoesNotThrow(()->endpoint.start("cap-a"));verify(registry).start("cap-a");}
    @Test void catalogLinkRequiresAssetAndModelPermissionsInTheBatchProject(){var catalog=mock(WarehouseCatalogService.class);var endpoint=new WarehouseBatchController(mock(WarehouseBatchRegistry.class),mock(WarehouseBatchExecutor.class),spaces,catalog,operations);assertThrows(AccessDeniedException.class,()->endpoint.linkCatalog("cap-b"));verifyNoInteractions(catalog);assertDoesNotThrow(()->endpoint.linkCatalog("cap-a"));verify(catalog).link("cap-a");}
    @Test void qualityReadAndRunAreSeparateWithinTheAssessmentProject(){var quality=mock(WarehouseQualityService.class);var endpoint=new WarehouseQualityController(quality,operations);assertDoesNotThrow(()->endpoint.get("assessment-b"));assertThrows(AccessDeniedException.class,()->endpoint.start("assessment-b"));verify(quality,never()).start("assessment-b");assertDoesNotThrow(()->endpoint.start("assessment-a"));verify(quality).start("assessment-a");}
    @Test void qualityPolicyCreationCannotBorrowWriterPermissions(){var quality=mock(WarehouseQualityService.class);var endpoint=new WarehouseQualityController(quality,operations);var request=new WarehouseQualityService.PolicyRequest();request.setSpaceId(900143L);assertThrows(AccessDeniedException.class,()->endpoint.createPolicy(request));verifyNoInteractions(quality);request.setSpaceId(900144L);assertDoesNotThrow(()->endpoint.createPolicy(request));verify(quality).createPolicy(request);}
    @Test void publicationIsAuthorizedUsingActualReleaseOwnership(){var serving=mock(WarehouseServingService.class);var endpoint=new WarehouseServingController(serving,operations,new ClientResourceAccess(jdbc,permissions));assertThrows(AccessDeniedException.class,()->endpoint.publish("release-b"));verifyNoInteractions(serving);assertDoesNotThrow(()->endpoint.publish("release-a"));verify(serving).publish("release-a");}
    @Test void targetConfigurationNeedsConnectionEditInTheSpaceProject(){var serving=mock(WarehouseServingService.class);var endpoint=new WarehouseServingController(serving,operations,new ClientResourceAccess(jdbc,permissions));var request=new WarehouseServingController.TargetRequest();request.setSpaceId(900144L);request.setDatasourceId(12);request.setDatabase("fixture");assertThrows(AccessDeniedException.class,()->endpoint.target(request));verifyNoInteractions(serving);}
    @Test void applicationScopeCannotBypassClientOwnershipThroughWarehouseEndpoint(){var serving=mock(WarehouseServingService.class);var endpoint=new WarehouseServingController(serving,operations,new ClientResourceAccess(jdbc,permissions));var request=new WarehouseServingController.ScopeRequest();request.setSpaceId(900144L);request.setClientId(12L);assertThrows(AccessDeniedException.class,()->endpoint.scope(request));verifyNoInteractions(serving);request.setClientId(900001L);assertDoesNotThrow(()->endpoint.scope(request));verify(serving).scope(eq(900144L),eq(900001L),anyList(),anyList(),anyList());}
    @Test void applicationScopeResponseTellsReadonlyClientOwnerItCannotEdit(){var serving=mock(WarehouseServingService.class);when(serving.scope(900144L,12L)).thenReturn(Map.of("locations",List.of(),"columns",List.of(),"maskedColumns",List.of()));var endpoint=new WarehouseServingController(serving,operations,new ClientResourceAccess(jdbc,permissions));var result=endpoint.scope(900144L,12L);assertEquals(false,((Map<?,?>)result.getData()).get("canEdit"));}
    @Test void unassignedConnectionFailsEvenWithFunctionPermission(){tx.executeWithoutResult(status->{jdbc.update("DELETE FROM da_datasource_project_rel WHERE datasource_id=9 AND project_id=144");assertThrows(AccessDeniedException.class,()->operations.space(900144L,"dp:model:edit"));status.setRollbackOnly();});}
    @Test void legacyModelsDoNotBorrowProjectPermissionsWithoutGlobalGrant(){var legacy=new WarehouseDefinition();legacy.setId(900003L);when(models.getInternal(900003L)).thenReturn(legacy);assertThrows(AccessDeniedException.class,()->operations.model(900003L,"dp:model:edit"));}
}
